import { View, throwError } from 'cerebral'
import { Component, forwardRef } from 'inferno'
import { createElement } from 'inferno-create-element'
import PropTypes from 'prop-types'

class BaseComponent extends Component {
  constructor(dependencies, mergeProps, props, controller, name) {
    super(props)
    if (!controller) {
      throwError(
        'Can not find controller, did you remember to use the Container component? Read more at: https://cerebraljs.com/docs/views/inferno.html'
      )
    }

    this.onUpdate = this.onUpdate.bind(this)
    this.view = new View({
      dependencies,
      mergeProps,
      props,
      controller,
      displayName: name,
      onUpdate: this.onUpdate,
    })
    this.view.mount()

    // Track unmount state explicitly
    this.isComponentUnmounted = false
  }

  /*
    We only allow forced render by change of props passed
    or Container tells it to render
  */
  shouldComponentUpdate(nextProps) {
    return this.view.onPropsUpdate(this.props, nextProps)
  }

  /*
    We have to update any usage of "get" when the component mounts
  */
  componentDidMount() {
    if (this.view.dynamicDependencies.length) {
      this.view.update(this.props)
    }
    this.isComponentUnmounted = false
  }

  /*
    We have to update any usage of "get" when the component updates
  */
  componentDidUpdate() {
    if (this.view.dynamicDependencies.length) {
      this.view.update(this.props)
    }
  }

  /*
    Unregister with existing state dependencies
  */
  componentWillUnmount() {
    this.view.unMount()
    this.isComponentUnmounted = true
  }

  onUpdate(stateChanges, force) {
    if (this.isComponentUnmounted) return
    this.view.updateFromState(stateChanges, this.props, force)
    this.forceUpdate()
  }
}

export default function HOC(dependencies, mergeProps, Component) {
  class CerebralComponent extends BaseComponent {
    constructor(props, context) {
      super(
        dependencies,
        mergeProps,
        props,
        context.controller,
        Component.displayName || Component.name
      )
    }

    toJSON() {
      return Component.displayName || Component.name || this.view._displayName
    }

    render() {
      return this.view.render(this.props, (componentProps) =>
        createElement(Component, componentProps)
      )
    }
  }

  CerebralComponent.displayName = `CerebralWrapping_${
    Component.displayName || Component.name
  }`

  CerebralComponent.contextTypes = {
    controller: PropTypes.object,
  }

  if (forwardRef) {
    // For Inferno version 6 or newer, use forwardRef to handle references properly
    const WrappedComponent = forwardRef((props, ref) => {
      return createElement(CerebralComponent, {
        ...props,
        ref,
      })
    })

    WrappedComponent.displayName = CerebralComponent.displayName
    WrappedComponent.contextTypes = CerebralComponent.contextTypes

    WrappedComponent.toJSON = () => Component.displayName || Component.name

    return WrappedComponent
  }

  return CerebralComponent
}
